WITH with_windows AS (SELECT *, LEAD(cost) OVER w_running AS next_cost, LAG(cost) OVER w_running AS prev_cost, LEAD(stock_qty) OVER w_running AS next_stock_qty, ROW_NUMBER() OVER w_running AS row_seq, LAST_VALUE(price, TRUE) OVER (PARTITION BY category, brand ORDER BY price ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_price FROM products WINDOW w_running AS (PARTITION BY category ORDER BY launch_date ASC, id ASC)), enriched AS (SELECT s.id, s.product_name, s.brand, s.price, s.launch_date, s.supplier_id, s.next_cost, s.prev_cost, s.next_stock_qty, s.row_seq, s.last_known_price, b.country, b.supplier_name, b.city FROM with_windows s LEFT JOIN suppliers b ON s.supplier_id = b.id), metrics AS (SELECT id, next_cost, prev_cost, row_seq, last_known_price, country, city, COUNT(next_cost) OVER w_ordered AS last4_count_next_cost, AVG(next_cost) OVER w_ordered AS last4_avg_next_cost, SUM(next_cost) OVER w_ordered AS last4_sum_next_cost, MAX(next_cost) OVER w_ordered AS last4_max_next_cost FROM enriched WINDOW w_ordered AS (PARTITION BY supplier_id ORDER BY next_stock_qty ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)), not_flagged AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM store_sales c WHERE c.product_id = s.id AND c.store_id = 3)) SELECT * FROM (SELECT id, city, last4_sum_next_cost, next_cost FROM not_flagged) src UNPIVOT (value FOR metric IN (last4_sum_next_cost, next_cost));
